from itertools import product
from typing import Sequence

Perm = tuple[int, ...]


def build_field(p: int, k: int, modulus: Sequence[int]) -> tuple[list[list[int]], list[list[int]]]:
    """Addition/multiplication tables of GF(p^k) = F_p[x]/(modulus); modulus is monic,
    coefficients listed from low to high degree; elements are integers in base p."""
    q = p ** k

    def digits(a: int) -> list[int]:
        return [(a // p ** i) % p for i in range(k)]

    def undigits(d: Sequence[int]) -> int:
        return sum((x % p) * p ** i for i, x in enumerate(d))

    def mul(a: int, b: int) -> int:
        x, y = digits(a), digits(b)
        prod_ = [0] * (2 * k - 1)
        for i, j in product(range(k), range(k)):
            prod_[i + j] = (prod_[i + j] + x[i] * y[j]) % p
        for deg in range(2 * k - 2, k - 1, -1):
            c = prod_[deg]
            if c:
                for i in range(k + 1):
                    prod_[deg - k + i] = (prod_[deg - k + i] - c * modulus[i]) % p
        return undigits(prod_[:k])

    add_t = [[undigits([u + v for u, v in zip(digits(a), digits(b))]) for b in range(q)] for a in range(q)]
    mul_t = [[mul(a, b) for b in range(q)] for a in range(q)]
    return add_t, mul_t


def affine_group(p: int, k: int, modulus: Sequence[int]) -> list[tuple[Perm, int]]:
    """All maps t -> a t + b of GF(q), each paired with its abelianization label log_g(a)."""
    q = p ** k
    add_t, mul_t = build_field(p, k, modulus)

    def order(a: int) -> int:
        x, n = a, 1
        while x != 1:
            x, n = mul_t[x][a], n + 1
        return n

    g = next(a for a in range(1, q) if order(a) == q - 1)
    out: list[tuple[Perm, int]] = []
    a = 1
    for e in range(q - 1):
        for b in range(q):
            out.append((tuple(add_t[mul_t[a][t]][b] for t in range(q)), e))
        a = mul_t[a][g]
    return out


if __name__ == "__main__":
