Perm = tuple[int, ...]


def compose(p: Perm, q: Perm) -> Perm:
    return tuple(p[q[i]] for i in range(len(p)))


def inverse(p: Perm) -> Perm:
    inv = [0] * len(p)
    for i, x in enumerate(p):
        inv[x] = i
    return tuple(inv)


def derived_subgroup(G: list[Perm]) -> set[Perm]:
    """Close the set of commutators x y x^-1 y^-1 under multiplication."""
    H = {compose(compose(x, y), compose(inverse(x), inverse(y))) for x in G for y in G}
    while True:
        new = H | {compose(a, b) for a in H for b in H}
        if new == H:
            return H
        H = new


def certify_abelianization(G: list[Perm], label: dict[Perm, int], n: int) -> bool:
    """Check that `label` is a homomorphism G -> Z/n whose kernel is exactly [G,G]."""
    D = derived_subgroup(G)
    hom = all((label[compose(x, y)] - label[x] - label[y]) % n == 0 for x in G for y in G)
    return hom and {g for g in G if label[g] % n == 0} == D and len(set(label.values())) == n


if __name__ == "__main__":
    EXP = [1, 2, 4, 3, 6, 7, 5]

    def gmul(a: int, b: int) -> int:
        r = 0
        for i in range(3):
            if (b >> i) & 1:
                r ^= a << i
        for d in (4, 3):
            if r >> d & 1:
                r ^= 0b1011 << (d - 3)
        return r

    G, lab = [], {}
    for e in range(7):
        for b in range(8):
            s = tuple(gmul(EXP[e], t) ^ b for t in range(8))
            G.append(s); lab[s] = e
    print(len(derived_subgroup(G)), certify_abelianization(G, lab, 7))  # 8 True

from math import log2


def binary_entropy(p: float) -> float:
    return 0.0 if p in (0.0, 1.0) else -p * log2(p) - (1 - p) * log2(1 - p)


def detector_value(n: int) -> float:
    """Detector Law: I(coset;T) = log2 n - ((n-1)/n) log2(n-1) = h(1/n), n = |G^ab| >= 2."""
    if n < 2:
        raise ValueError("need n >= 2")
    return log2(n) - (n - 1) / n * log2(n - 1)


def detector_rate_bound(n: int) -> float:
    """Proven upper bound (log2 n + 3)/n."""
    return (log2(n) + 3) / n


def pair_detector_value(n: int) -> float:
    """Conjectured semiprime law delta_2(n) (confirmed exactly at n = 3, 4, 7, 31)."""
    if n == 2:
        return 1.0
    Hn = log2(n - 1) / (n - 1) + (n - 2) / (n - 1) * log2((n - 1) ** 2 / (n - 2))
    return log2(n) - 2 * (n - 1) / n ** 2 * log2(n - 1) - ((n - 1) / n) ** 2 * Hn


if __name__ == "__main__":
    for n in (3, 4, 7, 31, 127):
        d = detector_value(n)
        assert abs(d - binary_entropy(1 / n)) < 1e-12 and d <= detector_rate_bound(n)
        print(f"n={n:4d} cap={log2(n):.4f} I1={d:.6f} ({100*d/log2(n):.2f}% of cap) "
              f"bound={detector_rate_bound(n):.4f} I2~{pair_detector_value(n):.6f}")

from math import gcd, log2


def euler_phi(d: int) -> int:
    return sum(1 for k in range(1, d + 1) if gcd(k, d) == 1)


def resolved_quotient_channel(q: int) -> float:
    """Conjectured (Coarsest-Resolved-Quotient Law) prime channel of AGL(1,q):
    the entropy of the multiplicative order of a uniform multiplier in the cyclic group F_q^*.
      I1 = log2(q-1) - sum_{d | q-1} (phi(d)/(q-1)) log2 phi(d)."""
    n = q - 1
    return log2(n) - sum(euler_phi(d) / n * log2(euler_phi(d)) for d in range(1, n + 1) if n % d == 0)


if __name__ == "__main__":
    for q in (4, 5, 7, 8, 9, 13, 16, 32):
        print(q, round(resolved_quotient_channel(q), 6))

