    return r


def cycle_type(p: tuple) -> tuple:
    seen, out = set(), []
    for i in range(len(p)):
        if i not in seen:
            j, L = i, 0
            while j not in seen:
                seen.add(j); j = p[j]; L += 1
            out.append(L)
    return tuple(sorted(out))


